// Настройка режима ноды Code: "Run Once for All Items"

const items = $input.all();

// Форматируем красивую сегодняшнюю дату
const todayStr = new Date().toLocaleDateString('ru-RU', { 
    day: 'numeric', 
    month: 'long', 
    weekday: 'long',
    timeZone: 'Europe/Moscow' 
});

// Если на сегодня ничего нет
if (!items.length || Object.keys(items[0].json).length === 0) {
    return [{
        json: {
            text: `📅 *Расписание на сегодня (${todayStr})*\n\nНа сегодня задач и пар нет. Можно спокойно отдохнуть или заняться своими проектами!`
        }
    }];
}

// Хелпер для обрезки секунд (10:15:00 -> 10:15)
const formatTime = (t) => t ? String(t).slice(0, 5) : null;

// Маппинг иконок по типу события
const typeIcons = {
    university: '🎓',
    task: '📌',
    note: '📝'
};

let lines = [`📅 *Расписание на сегодня (${todayStr}):*\n`];

for (const item of items) {
    const ev = item.json;

    // Собираем временной интервал
    const start = formatTime(ev.time_start);
    const end = formatTime(ev.time_end);
    let timeBlock = '🕒 *Весь день*';
    if (start && end) {
        timeBlock = `🕒 *${start} – ${end}*`;
    } else if (start) {
        timeBlock = `🕒 *${start}*`;
    }

    // Иконка и пометка важности
    const icon = ev.is_important ? '🔥' : (typeIcons[ev.item_type] || '•');

    // Очищаем описание от технического маркера [skip_regular_id: X] перед показом юзеру
    let cleanDesc = '';
    if (ev.description) {
        const stripped = ev.description.replace(/\[skip_regular_id:\s*\d+\]/g, '').trim();
        if (stripped) {
            cleanDesc = `\n   _${stripped}_`;
        }
    }

    lines.push(`${timeBlock} | ${icon} ${ev.title}${cleanDesc}`);
}

return [{
    json: {
        text: lines.join('\n')
    }
}];

