// Забираем ответ из структуры ИИ
const aiText = $input.first().json.output || $input.first().json.text || "";
const userId = $('Telegram Trigger').item.json.message.chat.id;

let extractedJson = [];

// Глобальное регулярное выражение с флагами 'g' (глобальный) и 's' (включая переносы строк)
const jsonRegex = /```json\s*([\s\(\S\)]*?)\s*```/gs;
let match;

// Находим абсолютно все блоки ```json ... ``` в ответе ИИ
while ((match = jsonRegex.exec(aiText)) !== null) {
  try {
    const rawJson = JSON.parse(match[1].trim());

    // Если внутри блока массив — распаковываем его, если объект — просто пушим
    if (Array.isArray(rawJson)) {
      extractedJson.push(...rawJson);
    } else {
      extractedJson.push(rawJson);
    }
  } catch (e) {
    console.error("Ошибка парсинга одного из блоков JSON от ИИ:", e);
  }
}

// Вычищаем все технические JSON-блоки из сообщения для пользователя
const cleanText = aiText.replace(jsonRegex, "").trim();

// Защитная проверка: авто-замена дефисов во времени на двоеточия
for (let action of extractedJson) {
  if (action.time_start && typeof action.time_start === 'string') {
    action.time_start = action.time_start.replace('-', ':');
  }
  if (action.time_end && typeof action.time_end === 'string') {
    action.time_end = action.time_end.replace('-', ':');
  }
}

// ЕСЛИ ЭКШЕНОВ НЕТ (Пользователь просто общается)
if (extractedJson.length === 0) {
  return [{
    json: {
      text: cleanText || "Готово!",
      chat_id: userId,
      has_action: false,
      action_data: null,
      is_ai: true
    }
  }];
}

// ЕСЛИ ЭКШЕНЫ ЕСТЬ: возвращаем массив элементов для запуска цикла n8n
return extractedJson.map(action => {
  return {
    json: {
      text: cleanText || "Планы обновлены! 👍",
      chat_id: userId,
      has_action: true,
      action_data: action
    }
  };
});
